//! 🔀️ Variant selection retains actual original discriminators and bounded schema comparisons.
use crate::{NativeDecodeControl,OriginalReceivingPrimary,RetainedWorkOutcome,RetirementDemand,RetainedCloneGrant,RetainedCloneProgress,RetainedCloneStep,ValueError,retained_clone::{RetainedCloneBinding,RetainedCloneClose,RetainedCloneRef,retained_clone_grant_admits},owned::{NativeRecordMatcher,NativeRecordSchema,NativeSchemaFields,NativeSchemaLeaf,NativeSchemaKeySource,NativeFieldMatch,tree::{NativeValueSource,NativeTreeKind,fixed,receipt,invalid,nested,child_grant}}};
#[derive(Clone,Copy)]pub struct NativeVariantSpec{pub all:NativeSchemaFields,pub units:NativeSchemaFields,pub data:NativeSchemaFields,pub count:usize,pub tag:Option<NativeSchemaFields>}
#[derive(Clone,Copy,Debug,PartialEq,Eq)]pub struct NativeVariantSelection{pub index:usize,pub direct:bool}
pub struct NativeVariantSelector<I:NativeValueSource+?Sized>{binding:Option<RetainedCloneBinding>,matcher:Option<NativeRecordMatcher<I>>,spec:NativeVariantSpec,selection:Option<NativeVariantSelection>,tag:Option<usize>,scan:usize,phase:u8,direct:bool,closing:bool,failed:bool}
impl<I:NativeValueSource+?Sized>NativeVariantSelector<I>{
 pub fn new(spec:NativeVariantSpec)->Self{Self{binding:None,matcher:None,spec,selection:None,tag:None,scan:0,phase:0,direct:false,closing:false,failed:false}}
 pub fn result(&self)->Option<NativeVariantSelection>{self.selection}
 pub fn validate_input(&self,input:RetainedCloneRef<'_,I>)->Result<(),ValueError>{input.check_binding(&self.binding)?;Ok(())}
 pub fn demands(&self,input:RetainedCloneRef<'_,I>,body:usize,maximum_work_units:u64)->Result<RetirementDemand,ValueError>{if self.closing{return Err(invalid())}if self.selection.is_some()||self.failed{return Ok(Default::default())}if !input.check_binding(&self.binding)?{return Ok(fixed(input.binding_copy_bytes()))}if let Some(matcher)=self.matcher.as_ref(){if self.phase==3{return self.settlement_demand(body)}if matcher.result().is_none(){return nested(matcher.demands(input,body,maximum_work_units)?,0)}}Ok(fixed(0))}
 /// 🧭️ Selects the resident matcher or the one separately funded local selector action.
 pub fn select_advance(&self,input:RetainedCloneRef<'_,I>,body:usize,maximum_work_units:u64)->Result<crate::owned::NativeAdvanceSelection,ValueError>{
  if self.closing||self.failed||self.selection.is_some(){return Err(invalid())}
  let work=if !input.check_binding(&self.binding)?{input.binding_work_demand(&self.binding)?}else if let Some(matcher)=self.matcher.as_ref(){if self.phase==3{self.settlement_work_demand(body)?}else if matcher.result().is_none(){return Ok(crate::owned::NativeAdvanceSelection::Nested)}else{1}}else{1};
  if work>maximum_work_units{return Err(ValueError::literal(crate::ValueRefusalKind::WorkLimit,"native variant action exceeds its original work ceiling"))}Ok(crate::owned::NativeAdvanceSelection::Local{work})
 }
 /// 🪢️ Polls only the resident record matcher.
 pub fn advance_nested(&mut self,input:RetainedCloneRef<'_,I>,control:&mut NativeDecodeControl<'_>,body:usize,maximum_work_units:u64,g:RetainedCloneGrant)->crate::RetainedWorkPoll<RetainedCloneStep,OriginalReceivingPrimary>{
  match self.matcher.as_mut(){Some(matcher) if self.phase!=3&&matcher.result().is_none()=>matcher.advance(input,control,body,maximum_work_units,child_grant(g,0)).map(|s|RetainedCloneStep::Progress(s.progress())),_=>crate::RetainedWorkPoll::Complete(RetainedWorkOutcome{result:Err(invalid().into()),work:0})}
 }
 /// 📬️ Runs one local selector action under the caller's original effect; `None` means the effect stayed pending.
 pub fn advance_local(&mut self,input:RetainedCloneRef<'_,I>,body:usize,effect:&mut crate::RetainedAllocationEffect<'_>)->Result<Option<RetainedCloneStep>,OriginalReceivingPrimary>{
  let d=self.demands(input,body,effect.maximum_work_units())?;if !retained_clone_grant_admits(effect.grant(),d){return Ok(Some(RetainedCloneStep::Progress(Default::default())))}
  if self.binding.is_none(){let turn=input.bind(&mut self.binding,effect);return turn.result.map(|p|Some(RetainedCloneStep::Progress(p.unwrap_or_default()))).map_err(Into::into)}
  if self.phase==3&&self.matcher.is_some(){return match self.settle_step(effect){crate::RetainedWorkPoll::Pending{..}=>Ok(None),crate::RetainedWorkPoll::Complete(turn)=>turn.result.map(|s|Some(RetainedCloneStep::Progress(s.progress()))).map_err(Into::into)}}
  if !effect.performed(1)?{return Err(ValueError::literal(crate::ValueRefusalKind::WorkLimit,"native variant action exceeded its original work").into())}
  let result:Result<(),OriginalReceivingPrimary>=(||{match self.phase{
   0=>self.phase=1,
   1=>{if input.get().variant_tag().is_some(){self.direct=true;self.matcher=Some(NativeRecordMatcher::new(self.spec.all,self.spec.count,NativeSchemaKeySource::VariantTag));self.phase=4;}else if self.spec.tag.is_some(){self.phase=2;}else if input.get().tree_kind()==Some(NativeTreeKind::Text){self.matcher=Some(NativeRecordMatcher::new(self.spec.units,self.spec.count,NativeSchemaKeySource::Text));self.phase=4;}else if input.get().tree_kind().is_none(){self.matcher=Some(NativeRecordMatcher::new(self.spec.units,self.spec.count,NativeSchemaKeySource::EnumOrdinal));self.phase=4;}else{if input.get().record_len()?!=1{return Err(invalid().into())}self.matcher=Some(NativeRecordMatcher::new(self.spec.data,self.spec.count,NativeSchemaKeySource::RecordName(0)));self.phase=4;}},
   2=>{if let Some(matcher)=self.matcher.as_mut(){match matcher.result().ok_or_else(invalid)?{NativeFieldMatch::Field(_)=>{if self.tag.is_some(){self.failed=true;return Err(invalid().with_retained_progress(receipt(fixed(0))).into())}self.tag=Some(self.scan);},NativeFieldMatch::Ambiguous=>{self.failed=true;return Err(invalid().with_retained_progress(receipt(fixed(0))).into())},NativeFieldMatch::Missing=>{}}self.phase=3;}else{let count=input.get().record_len()?;if self.scan==count{let tag=self.tag.ok_or_else(invalid)?;self.matcher=Some(NativeRecordMatcher::new(self.spec.all,self.spec.count,NativeSchemaKeySource::RecordText(tag)));self.phase=4;}else{self.matcher=Some(NativeRecordMatcher::new(self.spec.tag.ok_or_else(invalid)?,1,NativeSchemaKeySource::Record(self.scan)));}}},
   3=>{self.matcher=None;self.scan+=1;self.phase=2;},
   4=>{let NativeFieldMatch::Field(index)=self.matcher.as_ref().ok_or_else(invalid)?.result().ok_or_else(invalid)?else{self.failed=true;return Err(invalid().with_retained_progress(receipt(fixed(0))).into())};if index>=self.spec.count{self.failed=true;return Err(invalid().with_retained_progress(receipt(fixed(0))).into())}self.selection=Some(NativeVariantSelection{index,direct:self.direct});self.phase=5;},
   _=>return Err(invalid().into()),
  }Ok(())})();result?;Ok(Some(if self.selection.is_some(){RetainedCloneStep::Complete(receipt(fixed(0)))}else{RetainedCloneStep::Progress(receipt(fixed(0)))}))
 }
 pub fn settlement_start_demand(&self)->RetirementDemand{self.matcher.as_ref().map_or(Default::default(),|matcher|matcher.begin_close_demand())}
 pub fn settlement_start_work_demand(&self)->u64{self.matcher.as_ref().map_or(0,|matcher|matcher.begin_close_work_demand())}
 pub fn begin_settlement_paid(&mut self,effect:&mut crate::RetainedAllocationEffect<'_>)->RetainedWorkOutcome{if let Some(matcher)=self.matcher.as_mut(){matcher.begin_close_paid(effect)}else{RetainedWorkOutcome{result:Ok(RetainedCloneStep::Complete(Default::default())),work:0}}}
 pub fn settled(&self)->bool{self.matcher.is_none()}
 pub fn settlement_demand(&self,body:usize)->Result<RetirementDemand,ValueError>{if let Some(matcher)=self.matcher.as_ref(){if matcher.terminal_is_empty(){Ok(fixed(std::mem::size_of::<Option<NativeRecordMatcher<I>>>()))}else if !matcher.close_started(){Ok(matcher.begin_close_demand())}else{nested(matcher.close_demands(body)?,0)}}else{Ok(Default::default())}}
 pub fn settlement_work_demand(&self,body:usize)->Result<u64,ValueError>{match self.matcher.as_ref(){None=>Ok(0),Some(matcher)=>if matcher.terminal_is_empty(){Ok(1)}else if !matcher.close_started(){Ok(matcher.begin_close_work_demand())}else{matcher.close_work_demand(body)}}}
 pub fn settle_step(&mut self,effect:&mut crate::RetainedAllocationEffect<'_>)->crate::OriginalRetirementPoll{use crate::RetainedWorkPoll::Complete;if self.matcher.is_none(){return Complete(RetainedWorkOutcome{result:Ok(RetainedCloneStep::Complete(Default::default())),work:0})}let g=effect.grant();let d=match self.settlement_demand(g.maximum_copy_bytes){Ok(d)=>d,Err(error)=>return Complete(RetainedWorkOutcome{result:Err(error.into()),work:0})};if !retained_clone_grant_admits(g,d){return Complete(RetainedWorkOutcome{result:Ok(RetainedCloneStep::Progress(Default::default())),work:0})}let matcher=self.matcher.as_mut().expect("retained matcher");if !matcher.close_started()&&!matcher.terminal_is_empty(){let turn=matcher.begin_close_paid(effect);return Complete(RetainedWorkOutcome{result:turn.result.map_err(Into::into),work:turn.work})}if !matcher.terminal_is_empty(){return matcher.close_step(&mut effect.nested(child_grant(g,0)))}if effect.maximum_work_units()==0{return Complete(RetainedWorkOutcome{result:Ok(RetainedCloneStep::Progress(Default::default())),work:0})}match effect.performed(1){Ok(true)=>{},Ok(false)=>return Complete(RetainedWorkOutcome{result:Err(ValueError::literal(crate::ValueRefusalKind::WorkLimit,"variant matcher release exceeded its work authority").into()),work:1}),Err(error)=>return Complete(RetainedWorkOutcome{result:Err(error.into()),work:1})}self.matcher=None;Complete(RetainedWorkOutcome{result:Ok(RetainedCloneStep::Progress(receipt(d))),work:1})}
 pub fn begin_close(&mut self){self.closing=true;}
 pub fn begin_close_demand(&self)->RetirementDemand{if self.closing{Default::default()}else{fixed(std::mem::size_of::<bool>())}}
 pub fn begin_close_work_demand(&self)->u64{u64::from(!self.closing)}
 pub fn begin_close_paid(&mut self,effect:&mut crate::RetainedAllocationEffect<'_>)->RetainedWorkOutcome{if self.closing{return RetainedWorkOutcome{result:Ok(RetainedCloneStep::Complete(Default::default())),work:0}}let d=self.begin_close_demand();if !retained_clone_grant_admits(effect.grant(),d)||effect.maximum_work_units()==0{return RetainedWorkOutcome{result:Ok(RetainedCloneStep::Progress(Default::default())),work:0}}match effect.performed(1){Ok(true)=>{},Ok(false)=>return RetainedWorkOutcome{result:Err(ValueError::literal(crate::ValueRefusalKind::WorkLimit,"variant close start exceeded its work authority")),work:1},Err(error)=>return RetainedWorkOutcome{result:Err(error),work:1}}self.closing=true;RetainedWorkOutcome{result:Ok(RetainedCloneStep::Complete(receipt(d))),work:1}}
 pub fn close_demands(&self,body:usize)->Result<RetirementDemand,ValueError>{if !self.closing{return Err(invalid())}if self.matcher.is_some(){return self.settlement_demand(body)}if self.binding.is_some(){return RetainedCloneBinding::close_demand(&self.binding,body)}if self.phase!=6{return Ok(fixed(std::mem::size_of::<Option<NativeVariantSelection>>()+std::mem::size_of::<Option<usize>>()+std::mem::size_of::<bool>()+std::mem::size_of::<u8>()))}Ok(Default::default())}
 pub fn close_work_demand(&self,body:usize)->Result<u64,ValueError>{if !self.closing{return Err(invalid())}if let Some(matcher)=self.matcher.as_ref(){return if !matcher.close_started(){Ok(matcher.begin_close_work_demand())}else if matcher.terminal_is_empty(){Ok(1)}else{matcher.close_work_demand(body)}}if self.binding.is_some(){return RetainedCloneBinding::close_work_demand(&self.binding,body)}Ok(u64::from(self.phase!=6))}
 pub fn close_step(&mut self,effect:&mut crate::RetainedAllocationEffect<'_>)->crate::OriginalRetirementPoll{use crate::RetainedWorkPoll::Complete;if self.terminal_is_empty(){return Complete(RetainedWorkOutcome{result:Ok(RetainedCloneStep::Complete(Default::default())),work:0})}if self.requires_original_birth()||self.requires_original_control(){return Complete(RetainedWorkOutcome{result:Err(ValueError::literal(crate::ValueRefusalKind::UnsupportedOwner,"variant close requires its selected original control").into()),work:0})}let g=effect.grant();let d=match self.close_demands(g.maximum_copy_bytes){Ok(d)=>d,Err(error)=>return Complete(RetainedWorkOutcome{result:Err(error.into()),work:0})};if !retained_clone_grant_admits(g,d){return Complete(RetainedWorkOutcome{result:Ok(RetainedCloneStep::Progress(Default::default())),work:0})}if self.matcher.is_some(){return self.settle_step(effect)}if self.binding.is_some(){return RetainedCloneBinding::close_one(&mut self.binding,effect).map(|step|RetainedCloneStep::Progress(step.progress()))}if effect.maximum_work_units()==0{return Complete(RetainedWorkOutcome{result:Ok(RetainedCloneStep::Progress(Default::default())),work:0})}match effect.performed(1){Ok(true)=>{},Ok(false)=>return Complete(RetainedWorkOutcome{result:Err(ValueError::literal(crate::ValueRefusalKind::WorkLimit,"variant close exceeded its work authority").into()),work:1}),Err(error)=>return Complete(RetainedWorkOutcome{result:Err(error.into()),work:1})}self.selection=None;self.tag=None;self.failed=false;self.phase=6;Complete(RetainedWorkOutcome{result:Ok(RetainedCloneStep::Complete(receipt(d))),work:1})}
 /// 👶️ Selects the actual matcher or binding original Birth.
 pub fn requires_original_birth(&self)->bool{if let Some(matcher)=self.matcher.as_ref(){return !matcher.terminal_is_empty()&&matcher.requires_original_birth()}RetainedCloneBinding::requires_original_birth(&self.binding)}
 /// 🧵️ Relays the selected original Birth loan.
 pub fn close_original_birth_step(&mut self,original:&mut crate::OriginalRetirementCloseLoan<'_>,grant:RetainedCloneGrant)->crate::OriginalRetirementPoll{if let Some(matcher)=self.matcher.as_mut(){if !matcher.terminal_is_empty()&&matcher.requires_original_birth(){if grant.maximum_items==0||grant.maximum_depth==0{return crate::RetainedWorkPoll::Complete(RetainedWorkOutcome{result:Ok(RetainedCloneStep::Progress(Default::default())),work:0})}return matcher.close_original_birth_step(original,child_grant(grant,0))}}if self.matcher.is_none()&&RetainedCloneBinding::requires_original_birth(&self.binding){return RetainedCloneBinding::close_original_birth_step(&mut self.binding,original,grant)}crate::RetainedWorkPoll::Complete(RetainedWorkOutcome{result:Err(ValueError::literal(crate::ValueRefusalKind::UnsupportedOwner,"variant has no selected original Birth").into()),work:0})}
 /// 🪪️ Reports the selected actual matcher or binding control.
 pub fn requires_original_control(&self)->bool{if let Some(matcher)=self.matcher.as_ref(){return !matcher.terminal_is_empty()&&matcher.requires_original_control()}RetainedCloneBinding::requires_original_control(&self.binding)}
 /// 🔁️ Relays the actual selected original control on the same effect.
 pub fn close_original_step(&mut self,original:&mut crate::OriginalRetirementCloseLoan<'_>,effect:&mut crate::RetainedAllocationEffect<'_>)->crate::OriginalRetirementPoll{if self.requires_original_birth(){return crate::RetainedWorkPoll::Complete(RetainedWorkOutcome{result:Err(ValueError::literal(crate::ValueRefusalKind::UnsupportedOwner,"settle variant original Birth first").into()),work:0})}if let Some(matcher)=self.matcher.as_mut(){if !matcher.terminal_is_empty()&&matcher.requires_original_control(){let g=effect.grant();if g.maximum_items==0||g.maximum_depth==0{return crate::RetainedWorkPoll::Complete(RetainedWorkOutcome{result:Ok(RetainedCloneStep::Progress(Default::default())),work:0})}return matcher.close_original_step(original,&mut effect.reborrow(child_grant(g,0),effect.maximum_work_units()).expect("variant matcher close exceeds original effect"))}}if self.matcher.is_none()&&RetainedCloneBinding::requires_original_control(&self.binding){return RetainedCloneBinding::close_original_step(&mut self.binding,original,effect)}self.close_step(effect)}
 pub fn terminal_is_empty(&self)->bool{self.binding.is_none()&&self.matcher.is_none()&&(self.phase==6||self.phase==0)}
}
impl<I:NativeValueSource+?Sized>Drop for NativeVariantSelector<I>{fn drop(&mut self){assert!(std::thread::panicking()||self.terminal_is_empty(),"native variant selector requires funded closure")}}

#[path="🔢️unit/🦀️.rs"]mod unit;
pub use unit::{NativeUnitVariants,NativeUnitEnumReceiver};

use crate::owned::{NativeReceive,NativeReceiver,NativeAdvanceSelection,tree::{NativeReceiveSlot}};
use crate::{OriginalEffectReply,OriginalEffectReplyComplete};
use crate::retained_clone::RetainedOwnedProjection;
use std::mem::ManuallyDrop;
fn result_variant(index:usize)->Option<NativeRecordSchema>{["Ok","Err"].get(index).map(|name|NativeRecordSchema::Leaf(NativeSchemaLeaf{name,ordinal:index as u32}))}
fn result_unit(index:usize)->Option<NativeRecordSchema>{(index<2).then_some(NativeRecordSchema::Skip)}
pub struct NativeResultReceiver<I:NativeValueSource+?Sized,T:NativeReceive<dyn NativeValueSource>,E:NativeReceive<dyn NativeValueSource>>{selector:NativeVariantSelector<I>,ok:NativeReceiveSlot<dyn NativeValueSource,T>,err:NativeReceiveSlot<dyn NativeValueSource,E>,staged_ok:std::mem::ManuallyDrop<Option<T>>,staged_err:std::mem::ManuallyDrop<Option<E>>,retirement:RetainedCloneClose,closing:bool,taken:bool}
impl<I:NativeValueSource+?Sized,T:NativeReceive<dyn NativeValueSource>,E:NativeReceive<dyn NativeValueSource>> NativeReceive<I> for Result<T,E>{type Receiver=NativeResultReceiver<I,T,E>;fn receiver()->Self::Receiver{NativeResultReceiver{selector:NativeVariantSelector::new(NativeVariantSpec{all:unsafe{NativeSchemaFields::native(result_variant)},units:unsafe{NativeSchemaFields::native(result_unit)},data:unsafe{NativeSchemaFields::native(result_variant)},count:2,tag:None}),ok:Default::default(),err:Default::default(),staged_ok:std::mem::ManuallyDrop::new(None),staged_err:std::mem::ManuallyDrop::new(None),retirement:Default::default(),closing:false,taken:false}}}
impl<I:NativeValueSource+?Sized,T:NativeReceive<dyn NativeValueSource>,E:NativeReceive<dyn NativeValueSource>> NativeResultReceiver<I,T,E>{
 fn payload<'a>(&self,input:RetainedCloneRef<'a,I>)->Result<RetainedCloneRef<'a,dyn NativeValueSource>,ValueError>{let selected=self.selector.result().ok_or_else(invalid)?;if selected.direct{input.get().variant_payload()?;}else{input.get().record_child(0)?;}Ok(input.project(selected.index,move|value|if selected.direct{value.variant_payload().expect("bound Result variant payload")}else{value.record_child(0).expect("bound Result record payload")}))}
 fn child_ready(&self)->bool{self.selector.result().is_some_and(|selected|if selected.index==0{self.staged_ok.is_some()||self.ok.ready()}else{self.staged_err.is_some()||self.err.ready()})}
}
impl<I:NativeValueSource+?Sized,T:NativeReceive<dyn NativeValueSource>,E:NativeReceive<dyn NativeValueSource>> NativeReceiver<I,Result<T,E>> for NativeResultReceiver<I,T,E>{
 fn demands(&self,input:RetainedCloneRef<'_,I>,body:usize,maximum_work_units:u64)->Result<RetirementDemand,ValueError>{if self.closing||self.taken{return Err(invalid())}self.selector.validate_input(input)?;let Some(selected)=self.selector.result()else{return self.selector.demands(input,body,maximum_work_units)};if self.child_ready(){return self.selector.settlement_demand(body)}let payload=self.payload(input)?;nested(if selected.index==0{self.ok.demands(payload,body,maximum_work_units)?}else{self.err.demands(payload,body,maximum_work_units)?},0)}
 fn select_advance(&self,input:RetainedCloneRef<'_,I>,body:usize,maximum_work_units:u64)->Result<NativeAdvanceSelection,ValueError>{if self.closing||self.taken{return Err(invalid())}self.selector.validate_input(input)?;if self.selector.result().is_none(){return self.selector.select_advance(input,body,maximum_work_units)}if self.child_ready(){return Ok(NativeAdvanceSelection::Local{work:self.selector.settlement_work_demand(body)?})}Ok(NativeAdvanceSelection::Nested)}
 fn advance_nested(&mut self,input:RetainedCloneRef<'_,I>,control:&mut NativeDecodeControl<'_>,body:usize,maximum_work_units:u64,g:RetainedCloneGrant)->crate::RetainedWorkPoll<RetainedCloneStep,OriginalReceivingPrimary>{
  let Some(selected)=self.selector.result()else{return self.selector.advance_nested(input,control,body,maximum_work_units,g)};if self.child_ready(){return crate::RetainedWorkPoll::Complete(RetainedWorkOutcome{result:Err(invalid().into()),work:0})}
  let payload=match self.payload(input){Ok(payload)=>payload,Err(error)=>return crate::RetainedWorkPoll::Complete(RetainedWorkOutcome{result:Err(error.into()),work:0})};
  if selected.index==0{self.ok.advance(payload,control,body,maximum_work_units,child_grant(g,0)).map(|s|RetainedCloneStep::Progress(s.progress()))}else{self.err.advance(payload,control,body,maximum_work_units,child_grant(g,0)).map(|s|RetainedCloneStep::Progress(s.progress()))}
 }
 fn advance_local<'reply>(&mut self,input:RetainedCloneRef<'_,I>,body:usize,effect:&mut crate::RetainedAllocationEffect<'_>,reply:OriginalEffectReply<'reply,RetainedCloneStep,OriginalReceivingPrimary>)->Result<OriginalEffectReplyComplete<'reply,RetainedCloneStep,OriginalReceivingPrimary>,ValueError>{
  let result:Result<Option<RetainedCloneStep>,OriginalReceivingPrimary>=(||{if self.selector.result().is_none(){return self.selector.advance_local(input,body,effect)}if self.child_ready(){return match self.selector.settle_step(effect){crate::RetainedWorkPoll::Pending{..}=>Ok(None),crate::RetainedWorkPoll::Complete(turn)=>turn.result.map(|s|Some(RetainedCloneStep::Progress(s.progress()))).map_err(Into::into)}}Err(invalid().into())})();
  Ok(match result{Ok(Some(step))=>reply.complete(Ok(if self.output_ready(){RetainedCloneStep::Complete(step.progress())}else{RetainedCloneStep::Progress(step.progress())})),Ok(None)=>reply.pending(),Err(error)=>reply.complete(Err(error))})
 }
 fn output_ready(&self)->bool{!self.closing&&!self.taken&&self.child_ready()&&self.selector.settled()}
 semio_framework_value_native_receiver_protocol::result_output_engine!();
 semio_framework_value_native_receiver_protocol::native_receiver_close_start!(closing);
 semio_framework_value_native_receiver_protocol::result_close_engine!();
 fn terminal_is_empty(&self)->bool{self.ok.terminal_is_empty()&&self.err.terminal_is_empty()&&self.staged_ok.is_none()&&self.staged_err.is_none()&&self.retirement.is_empty()&&self.selector.terminal_is_empty()}
}

impl<I:NativeValueSource+?Sized,T:NativeReceive<dyn NativeValueSource>,E:NativeReceive<dyn NativeValueSource>> Drop for NativeResultReceiver<I,T,E>{fn drop(&mut self){let empty=self.terminal_is_empty();assert!(std::thread::panicking()||empty,"native result receiver requires funded closure");if empty{unsafe{std::mem::ManuallyDrop::drop(&mut self.staged_ok);std::mem::ManuallyDrop::drop(&mut self.staged_err);}}}}
